//! The RNG against LuaJIT in bulk: `tests/fixtures/rng_luajit_bulk.json` holds, for each of about
//! 200 run seeds, a digest of the values the game's own RNG functions produce under LuaJIT 2.1
//! over a fixed schedule of draws (about 10^6 `pseudoseed` draws in all), generated by
//! `scripts/luajit_rng_bulk_oracle.lua`, which documents the schedule. This test replays it with
//! `jackdaw_core::rng` and compares every run's value count and digest: a 64-bit FNV-1a over the
//! little-endian bytes of each value's IEEE-754 bit pattern.

use std::collections::HashMap;
use std::fmt::Write as _;
use std::path::PathBuf;

use jackdaw_core::rng::{self, Rng};
use serde_json::Value;

const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

fn fixture() -> Value {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/rng_luajit_bulk.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).expect("valid JSON")
}

fn num(v: &Value) -> f64 {
    f64::from_bits(u64::from_str_radix(v.as_str().expect("hex string"), 16).expect("hex"))
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|s| s.as_str().expect("string").to_owned())
        .collect()
}

fn sizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|n| n.as_u64().expect("size") as usize)
        .collect()
}

/// The oracle's `sort_id(i)`: distinct for `i < 10007`, and not monotonic in `i`.
fn sort_id(i: usize) -> f64 {
    (i * 7919 % 10007) as f64
}

/// The schedule's parameters, as the fixture records them.
struct Schedule {
    rounds: usize,
    ops: Vec<String>,
    keys: Vec<String>,
    ranges: Vec<(i64, i64)>,
    element_sizes: Vec<usize>,
    shuffle_sizes: Vec<usize>,
    /// Ids of the `element_keyed` table (`names[i]` has id `i + 1`) in Lua's key order (bytes).
    keyed_ids: Vec<f64>,
}

impl Schedule {
    fn new(fixture: &Value) -> Self {
        let mut names: Vec<(Vec<u8>, f64)> = strings(&fixture["names"])
            .into_iter()
            .zip(1..)
            .map(|(name, id)| (name.into_bytes(), f64::from(id)))
            .collect();
        names.sort_by(|a, b| a.0.cmp(&b.0));
        Self {
            rounds: fixture["rounds"].as_u64().expect("rounds") as usize,
            ops: strings(&fixture["ops"]),
            keys: strings(&fixture["keys"]),
            ranges: fixture["ranges"]
                .as_array()
                .expect("ranges")
                .iter()
                .map(|r| (r[0].as_i64().expect("lo"), r[1].as_i64().expect("hi")))
                .collect(),
            element_sizes: sizes(&fixture["element_sizes"]),
            shuffle_sizes: sizes(&fixture["shuffle_sizes"]),
            keyed_ids: names.into_iter().map(|(_, id)| id).collect(),
        }
    }
}

/// The running digest, with an optional trace in the format of the oracle's `--trace`.
struct Digest {
    hash: u64,
    count: u64,
    trace: Option<String>,
}

impl Digest {
    fn fold(&mut self, x: f64, round: usize, ki: usize, op: &str) {
        for byte in x.to_bits().to_le_bytes() {
            self.hash = (self.hash ^ u64::from(byte)).wrapping_mul(FNV_PRIME);
        }
        self.count += 1;
        if let Some(trace) = &mut self.trace {
            writeln!(trace, "{round} {ki} {op} {:016x}", x.to_bits()).unwrap();
        }
    }
}

/// Play one run of the schedule (see `scripts/luajit_rng_bulk_oracle.lua`).
fn replay(schedule: &Schedule, run: &Value, trace: bool) -> Digest {
    let seed = run["seed"].as_str().expect("seed");
    let hashed = run
        .get("hashed_seed")
        .map_or_else(|| rng::pseudohash(seed.as_bytes()), num);
    let streams: HashMap<String, f64> = run.get("streams").map_or_else(HashMap::new, |s| {
        s.as_object()
            .expect("streams")
            .iter()
            .map(|(key, value)| (key.clone(), num(value)))
            .collect()
    });
    let mut rng = Rng::from_parts(seed.to_owned(), hashed, streams);
    let mut digest = Digest {
        hash: FNV_OFFSET,
        count: 0,
        trace: trace.then(String::new),
    };
    digest.fold(rng.hashed_seed(), 0, 0, "hashed_seed");
    for (ki, key) in (1..).zip(&schedule.keys) {
        digest.fold(
            rng::pseudohash_parts(key.as_bytes(), seed.as_bytes()),
            0,
            ki,
            "hash",
        );
        digest.fold(rng::predict_seed(key, seed), 0, ki, "predict");
    }
    for round in 1..=schedule.rounds {
        for (ki, key) in (1..).zip(&schedule.keys) {
            let op = schedule.ops[(3 * round + ki) % schedule.ops.len()].as_str();
            let mut fold = |x: f64| digest.fold(x, round, ki, op);
            match op {
                "random" => fold(rng.random(key)),
                "seed" => fold(rng.seed(key)),
                "range" => {
                    let (lo, hi) = schedule.ranges[(round + ki) % schedule.ranges.len()];
                    fold(rng.random_range(key, lo, hi) as f64);
                }
                "element_array" | "element_sort_id" => {
                    let n = schedule.element_sizes[(round + 2 * ki) % schedule.element_sizes.len()];
                    if op == "element_array" {
                        // Keys 1..n in numeric order.
                        let index = rng::element_index(n, rng.seed(key));
                        fold((index + 1) as f64);
                    } else {
                        // Entries that carry a sort_id are drawn in sort_id order.
                        let mut entries: Vec<(f64, usize)> =
                            (1..=n).map(|i| (sort_id(i), i)).collect();
                        entries.sort_by(|a, b| a.0.total_cmp(&b.0));
                        let (id, i) = entries[rng::element_index(n, rng.seed(key))];
                        fold(id);
                        fold(i as f64);
                    }
                }
                "element_keyed" => {
                    let ids = &schedule.keyed_ids;
                    fold(ids[rng::element_index(ids.len(), rng.seed(key))]);
                }
                "shuffle_sort_id" | "shuffle_plain" => {
                    let m = schedule.shuffle_sizes[(round + 3 * ki) % schedule.shuffle_sizes.len()];
                    let mut list: Vec<f64> = if op == "shuffle_sort_id" {
                        // pseudoshuffle sorts entries that carry a sort_id first.
                        let mut ids: Vec<f64> = (1..=m).map(sort_id).collect();
                        ids.sort_by(f64::total_cmp);
                        ids
                    } else {
                        (1..=m).map(|i| i as f64).collect()
                    };
                    rng::shuffle(&mut list, rng.seed(key));
                    for x in list {
                        fold(x);
                    }
                }
                other => panic!("unknown op {other}"),
            }
        }
    }
    digest
}

#[test]
fn bulk_draws_match_luajit() {
    let fixture = fixture();
    let schedule = Schedule::new(&fixture);
    let runs = fixture["runs"].as_array().expect("runs");
    // Each scheduled op advances one stream once.
    let draws = (schedule.rounds * schedule.keys.len() * runs.len()) as u64;
    assert_eq!(fixture["total_draws"].as_u64(), Some(draws), "total_draws");
    assert!(draws >= 1_000_000, "the bulk fixture covers 10^6 draws");

    let mut failures = Vec::new();
    for (index, run) in runs.iter().enumerate() {
        let seed = run["seed"].as_str().expect("seed");
        if let Some(made_by) = run.get("random_string") {
            let length = made_by[0].as_u64().expect("length") as usize;
            let x = num(&made_by[1]);
            assert_eq!(
                rng::random_string(length, x),
                seed,
                "run {index}: random_string({length}, {x:e})"
            );
        }
        let got = replay(&schedule, run, false);
        let (want_count, want_hash) = (
            run["values"].as_u64().expect("values"),
            run["digest"].as_str().expect("digest"),
        );
        if got.count != want_count || format!("{:016x}", got.hash) != want_hash {
            let injected = run.get("hashed_seed").is_some() || run.get("streams").is_some();
            failures.push((
                index,
                format!(
                    "run {index} (seed {seed:?}{}): {} values, digest {:016x}; LuaJIT: \
                     {want_count} values, digest {want_hash}",
                    if injected { ", injected" } else { "" },
                    got.count,
                    got.hash,
                ),
            ));
        }
    }
    if let Some(&(index, _)) = failures.first() {
        // The first failing run's trace, for a line-by-line diff against LuaJIT's.
        let trace = replay(&schedule, &runs[index], true).trace.expect("trace");
        let path = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
            .join(format!("rng_luajit_bulk_run{index}.txt"));
        std::fs::write(&path, trace).expect("write trace");
        let lines: Vec<&str> = failures.iter().map(|(_, line)| line.as_str()).collect();
        panic!(
            "{} of {} runs differ from LuaJIT:\n  {}\nThe trace of run {index} is in {}; diff it \
             against `luajit scripts/luajit_rng_bulk_oracle.lua --trace {index}`.",
            failures.len(),
            runs.len(),
            lines.join("\n  "),
            path.display()
        );
    }
}
